        attributes: ["TRAM_STOP_TYPES — on the road, raised road, island, curb extension", "ROAD_GAP_M — 0.6 m: the gap at a stop on the road (STEP_FREE_M: core/mobility.js)", "CROSSOVER_M — 20 m: a crossover between two tracks, along them", "STOP_LINE_M — 2 m: the stop line of a stop's lights, before it", "CROSSING_M — 4 m: the crossing to an island"],
        operations: ["tramTracks(line, crossover) — the tracks a line uses: not round the turn at the end of a stub track, a crossover there", "tramRails(line, gauge, crossover) — both rails of each"],
